    {
      "category": "short_to_ground",
      "components": ["U11"],
      "pins": ["U11.13", "U11.14"],
      "nets": ["GND"],
      "observed": "The GND net directly contains SKW92A pins 13 and 14, which the netlist metadata identifies as LAN_PORT3_TX+ and LAN_PORT3_TX- and as bidirectional data pins.",
      "expected": "Ethernet PHY differential data pins should not be tied directly to GND unless the design explicitly uses those pins as ground. The specification documents the RJ45 jack as unconnected but does not specify grounding the module's Ethernet TX pins; unused or repurposed PHY/GPIO pins should be left floating/single-node or driven as intended GPIO, not shorted to ground.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(node (ref \"U11\") (pin \"13\") (pinfunction \"LAN_PORT3_TX+\") (pintype \"bidirectional\"))"
        },
        {
          "source": "netlist",
          "quote": "(node (ref \"U11\") (pin \"14\") (pinfunction \"LAN_PORT3_TX-\") (pintype \"bidirectional\"))"
        },
        {
          "source": "spec",
          "quote": "In this netlist export, the Ethernet jack is not wired to the SKW92A's Ethernet PHY nets."
        }
      ],
      "impact": "This shorts the unused Ethernet PHY transmit differential pair to ground. If the PHY is enabled, it can load or damage the transmit drivers and would prevent normal Ethernet operation even if the jack were later connected.",
      "confidence": 0.65
    }
  ],
  "summary": "Most connectivity matches the specification, but SKW92A pins 13 and 14 (LAN_PORT3_TX+/-) are tied directly to GND, which is not an intended power connection and is a likely short-to-ground anomaly."
}

